"""Explicit sparse packing for n=26: 4 large corner circles + 22 small fillers.

The sum is dominated by a few big wall-limited circles. We place 4 corner
circles at (0.2,0.2),(0.8,0.2),(0.2,0.8),(0.8,0.8) (each radius 0.2, limited
by its two walls), then fill 22 more sites with the largest feasible circle at
each grid point. Fully deterministic, O(n^2), no iterative optimizer.
"""
import numpy as np


def _wall(x, y):
    return min(x, y, 1.0 - x, 1.0 - y)


def construct_packing():
    n = 26
    placed = []  # (x, y, r)

    def max_radius(x, y):
        r = _wall(x, y)
        for (px, py, pr) in placed:
            d = np.hypot(x - px, y - py)
            v = d - pr
            if v < r:
                r = v
        return max(r, 0.0)

    # 4 large corner circles.
    for (x, y) in [(0.2, 0.2), (0.8, 0.2), (0.2, 0.8), (0.8, 0.8)]:
        placed.append((x, y, max_radius(x, y)))

    # Fill remaining sites: pick the grid point with the largest feasible radius
    # repeatedly (greedy largest-first), so fillers land in the biggest gaps.
    grid = [(gx, gy) for gx in np.linspace(0.05, 0.95, 19)
            for gy in np.linspace(0.05, 0.95, 19)]
    while len(placed) < n:
        best = None
        best_r = -1.0
        for (gx, gy) in grid:
            r = max_radius(gx, gy)
            if r > best_r:
                best_r = r
                best = (gx, gy)
        if best is None or best_r < 1e-6:
            break
        placed.append((best[0], best[1], best_r))

    centers = np.array([(p[0], p[1]) for p in placed])
    radii = np.array([p[2] for p in placed])
    return centers, radii, float(np.sum(radii))

